+export async function getPrompt(name, args = {}) {
+  const spec = PROMPT_ARGUMENTS[name];
+  if (!spec) {
+    const error = new Error(`Unknown prompt: ${name}`);
+    error.code = -32602;
+    throw error;
+  }
+
+  const allowed = Object.keys(spec);
+  const provided = Object.keys(args);
+  const extra = provided.filter((k) => !allowed.includes(k));
+  if (extra.length > 0) {
+    const error = new Error(`Unexpected argument(s): ${extra.join(', ')}`);
+    error.code = -32602;
+    throw error;
+  }
+
+  const resolved = {};
+  for (const argName of allowed) {
+    const argSpec = spec[argName];
+    if (args[argName] === undefined || args[argName] === null) {
+      if (argSpec.required) {
+        const error = new Error(`Missing required argument: ${argName}`);
+        error.code = -32602;
+        throw error;
+      }
+      resolved[argName] = argSpec.default;
+    } else {
+      resolved[argName] = args[argName];
+    }
+  }
